import sys
sys.setrecursionlimit(10**6)

def main():
    import sys

    input = sys.stdin.read
    data = input().split()
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        adj[u].append(v)
        adj[v].append(u)

    MOD = 10**9 + 7
    inv2 = (MOD + 1) // 2

    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    cycles = []

    def dfs(u, p):
        visited[u] = True
        parent[u] = p
        stack = [(u, iter(adj[u]))]

        while stack:
            curr, children = stack[-1]
            try:
                v = next(children)
                if v == p:
                    continue
                if visited[v]:
                    if v != parent[curr]:
                        path = []
                        node = curr
                        while node != v and node != 0:
                            path.append(node)
                            node = parent[node]
                        if node == v:
                            path.append(v)
                            cycles.append(path)
                else:
                    parent[v] = curr
                    stack.append((v, iter(adj[v])))
            except StopIteration:
                stack.pop()

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, 0)

    cycle_nodes = set()
    for cyc in cycles:
        for node in cyc:
            cycle_nodes.add(node)

    def power(a, b, m):
        res = 1
        a %= m
        while b > 0:
            if b % 2 == 1:
                res = (res * a) % m
            a = (a * a) % m
            b //= 2
        return res

    def inv(n, m):
        return power(n, m - 2, m)

    pow2_n = power(2, n, MOD)
    pow2_n_inv = inv(pow2_n, MOD)

    E_X = 0
    E_X2 = 0

    comp_count = 0
    visited_comp = [False] * (n + 1)

    def get_components():
        nonlocal comp_count
        comp_count = 0
        for i in range(1, n + 1):
            if not visited_comp[i]:
                comp_count += 1
                stack = [i]
                visited_comp[i] = True
                while stack:
                    u = stack.pop()
                    for v in adj[u]:
                        if not visited_comp[v]:
                            visited_comp[v] = True
                            stack.append(v)
        return comp_count

    get_components()

    term1 = (comp_count * pow2_n_inv) % MOD

    term2 = 0
    for i in range(1, n + 1):
        prob_i = inv2
        term2 = (term2 + prob_i) % MOD

    term2_sq = (term2 * term2) % MOD

    term3 = 0
    for u in range(1, n + 1):
        for v in adj[u]:
            if u < v:
                prob_uv = (inv2 * inv2) % MOD
                term3 = (term3 + prob_uv) % MOD

    E_X2 = (term2_sq + term3) % MOD
    E_X_sq = (term1 * term1) % MOD

    var = (E_X2 - E_X_sq) % MOD
    if var < 0:
        var += MOD

    print(var)

if __name__ == "__main__":
    main()
